    return (
        <section className={"reminders-preview"}>
            <a href={"/"}>View all <img src={bird} alt={"bird"}/></a>
            <div className={"reminders-container"}>

            </div>
            <button>View more</button>
        </section>
    );
};

export default RemindersPreview;
